def test_calculator_pipeline():
    filepath = os.path.join(EXAMPLES_DIR, "calculator.aayu")
    with open(filepath, "r") as f:
        source = f.read()
        
    lexer = Lexer(source)
    tokens = lexer.tokenize()
    parser = Parser(tokens)
    ast = parser.parse()
    compiler = AAYUCompiler()
    bytecode = compiler.compile(ast)
    assert len(bytecode.instructions) > 0

